from .repository import put_contact

def add_contact(connection, email, name):
    with connection:
        put_contact(connection, email, name)

def _validate_rows(rows):
    if not isinstance(rows, list):
        raise ValueError("rows must be a list")
    validated = []
    seen = set()
    for row in rows:
        if not isinstance(row, dict):
            raise ValueError("each contact must be an object")
        if set(row.keys()) != {"email", "name"}:
            raise ValueError("each contact must have exactly email and name fields")
        email = row["email"]
        name = row["name"]
        if not isinstance(email, str) or not isinstance(name, str):
            raise ValueError("email and name must be strings")
        email = email.strip()
        name = name.strip()
        if email.count("@") != 1:
            raise ValueError("email must contain exactly one @")
        local, domain = email.split("@")
        if not local or not domain:
            raise ValueError("email must have nonempty local and domain parts")
        if any(ch.isspace() for ch in email):
            raise ValueError("email must not contain whitespace")
        if not name:
            raise ValueError("name must be nonempty")
        email = email.lower()
        if email in seen:
            raise ValueError("duplicate email in batch: %s" % email)
        seen.add(email)
        validated.append((email, name))
    return validated

def import_contacts(connection, rows):
    validated = _validate_rows(rows)
    inserted = 0
    updated = 0
    with connection:
        for email, name in validated:
            existing = connection.execute(
                "SELECT name FROM contacts WHERE email = ?", (email,)
            ).fetchone()
            if existing is None:
                put_contact(connection, email, name)
                inserted += 1
            else:
                put_contact(connection, email, name)
                updated += 1
    return {"inserted": inserted, "updated": updated}
